 check(os.geteuid()==0 and sys.argv[1:] in ([],['--undo']),'Run with sudo; optional --undo only');os.umask(0o077)
 lock=open('/run/lock/gpd-egpu-loader.lock','a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 status=subprocess.run(['systemctl','is-active','gpd-egpu-auto.service'],capture_output=True,text=True,timeout=10).stdout.strip()
